public inherited sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName, List<String> fields, Map<String, Object> filters, String orderByField, Integer maxRows) {
        try {
            if (maxRows == null || maxRows < 1 || maxRows > 200) {
                throw new SearchException('maxRows must be between 1 and 200.');
            }
            if (fields == null || fields.isEmpty()) {
                throw new SearchException('Fields list cannot be null or empty.');
            }
            if (String.isBlank(objectApiName)) {
                throw new SearchException('Object API Name cannot be blank.');
            }

            SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName);
            if (sObjType == null) {
                throw new SearchException('Invalid object API name: ' + objectApiName);
            }

            DescribeSObjectResult objDescribe = sObjType.getDescribe();
            if (!objDescribe.isAccessible()) {
                throw new SearchException('Object is not accessible.');
            }

            Map<String, SObjectField> fieldMap = objDescribe.fields.getMap();

            Set<String> fieldsToSelect = new Set<String>{'id'};
            for (String f : fields) {
                SObjectField sof = fieldMap.get(f);
                if (sof == null) {
                    throw new SearchException('Invalid field: ' + f);
                }
                if (!sof.getDescribe().isAccessible()) {
                    throw new SearchException('Field not accessible: ' + f);
                }
                fieldsToSelect.add(f.toLowerCase());
            }

            String whereClause = '';
            Map<String, Object> binds = new Map<String, Object>();
            if (filters != null && !filters.isEmpty()) {
                List<String> conditions = new List<String>();
                Integer bindIdx = 0;
                for (String f : filters.keySet()) {
                    SObjectField sof = fieldMap.get(f);
                    if (sof == null) {
                        throw new SearchException('Invalid filter field: ' + f);
                    }
                    DescribeFieldResult dfr = sof.getDescribe();
                    if (!dfr.isAccessible()) {
                        throw new SearchException('Filter field not accessible: ' + f);
                    }
                    if (!dfr.isFilterable()) {
                        throw new SearchException('Field not filterable: ' + f);
                    }

                    String bindVar = 'val' + bindIdx;
                    binds.put(bindVar, filters.get(f));
                    conditions.add(f + ' = :' + bindVar);
                    bindIdx++;
                }
                whereClause = ' WHERE ' + String.join(conditions, ' AND ');
            }

            String orderByClause = '';
            if (String.isNotBlank(orderByField)) {
                SObjectField sof = fieldMap.get(orderByField);
                if (sof == null) {
                    throw new SearchException('Invalid order by field: ' + orderByField);
                }
                DescribeFieldResult dfr = sof.getDescribe();
                if (!dfr.isAccessible()) {
                    throw new SearchException('Order by field not accessible: ' + orderByField);
                }
                if (!dfr.isSortable()) {
                    throw new SearchException('Field not sortable: ' + orderByField);
                }
                orderByClause = ' ORDER BY ' + orderByField + ' ASC';
            }

            String query = 'SELECT ' + String.join(new List<String>(fieldsToSelect), ', ') + 
                           ' FROM ' + objectApiName + 
                           whereClause + 
                           orderByClause + 
                           ' LIMIT ' + maxRows;

            return Database.queryWithBinds(query, binds, AccessLevel.USER_MODE);

        } catch (SearchException se) {
            throw se;
        } catch (Exception e) {
            throw new SearchException(e.getMessage());
        }
    }
}
