public with sharing class ContactLookupAction {

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact Id')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;
    }

    @InvocableMethod(label='Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        Set<String> emailsToSearch = new Set<String>();

        for (Request req : requests) {
            if (String.isNotBlank(req.email)) {
                emailsToSearch.add(req.email.trim().toLowerCase());
            }
        }

        Map<String, Id> emailToContactId = new Map<String, Id>();

        if (!emailsToSearch.isEmpty()) {
            for (Contact c : [
                SELECT Id, Email 
                FROM Contact 
                WHERE Email IN :emailsToSearch 
                ORDER BY CreatedDate ASC
            ]) {
                if (String.isNotBlank(c.Email)) {
                    String normalizedEmail = c.Email.toLowerCase();
                    if (!emailToContactId.containsKey(normalizedEmail)) {
                        emailToContactId.put(normalizedEmail, c.Id);
                    }
                }
            }
        }

        for (Request req : requests) {
            Result res = new Result();
            if (String.isNotBlank(req.email)) {
                String normalizedEmail = req.email.trim().toLowerCase();
                if (emailToContactId.containsKey(normalizedEmail)) {
                    res.contactId = emailToContactId.get(normalizedEmail);
                    res.found = true;
                } else {
                    res.contactId = null;
                    res.found = false;
                }
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }
}
