public class OrderPayloadParser {
    public class PayloadException extends Exception {}

    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body cannot be null or blank');
        }

        Object parsedObject;
        try {
            parsedObject = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Invalid JSON');
        }

        if (!(parsedObject instanceof Map<String, Object>)) {
            throw new PayloadException('JSON must be an object');
        }

        Map<String, Object> root = (Map<String, Object>) parsedObject;
        Order ord = new Order();

        Object numObj = root.get('number');
        if (numObj == null || !(numObj instanceof String) || String.isBlank((String) numObj)) {
            throw new PayloadException('Missing or blank number');
        }
        ord.orderNumber = (String) numObj;

        Object dateObj = root.get('date');
        if (dateObj instanceof String) {
            try {
                ord.orderDate = Date.valueOf((String) dateObj);
            } catch (Exception e) {
                // Ignore invalid date format
            }
        }

        Object currObj = root.get('currency');
        if (currObj instanceof String) {
            ord.currencyCode = (String) currObj;
        }

        Object custObj = root.get('customer');
        if (custObj instanceof Map<String, Object>) {
            Map<String, Object> custMap = (Map<String, Object>) custObj;
            Object emailObj = custMap.get('email');
            if (emailObj instanceof String) {
                ord.customerEmail = (String) emailObj;
            }
        }

        ord.lines = new List<Line>();
        ord.total = 0.00;

        Object linesObj = root.get('lines');
        if (linesObj instanceof List<Object>) {
            for (Object lineObj : (List<Object>) linesObj) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    continue;
                }
                Map<String, Object> lineMap = (Map<String, Object>) lineObj;

                Line l = new Line();

                Object skuObj = lineMap.get('sku');
                if (skuObj == null || !(skuObj instanceof String) || String.isBlank((String) skuObj)) {
                    throw new PayloadException('Missing or blank sku');
                }
                l.sku = (String) skuObj;

                Object qtyObj = lineMap.get('quantity');
                if (qtyObj == null || !(qtyObj instanceof Integer || qtyObj instanceof Decimal || qtyObj instanceof Double)) {
                    throw new PayloadException('Missing quantity');
                }
                Decimal qtyDec = Decimal.valueOf(String.valueOf(qtyObj));
                if (qtyDec <= 0) {
                    throw new PayloadException('Non-positive quantity');
                }
                l.quantity = qtyDec.intValue();

                Object priceObj = lineMap.get('unitPrice');
                if (priceObj == null || !(priceObj instanceof Integer || priceObj instanceof Decimal || priceObj instanceof Double)) {
                    throw new PayloadException('Missing unitPrice');
                }
                Decimal priceDec = Decimal.valueOf(String.valueOf(priceObj));
                if (priceDec < 0) {
                    throw new PayloadException('Negative unitPrice');
                }
                l.unitPrice = priceDec;

                Object discObj = lineMap.get('discount');
                if (discObj != null && (discObj instanceof Integer || discObj instanceof Decimal || discObj instanceof Double)) {
                    l.discount = Decimal.valueOf(String.valueOf(discObj));
                } else {
                    l.discount = 0.0;
                }

                l.lineTotal = (l.quantity * l.unitPrice * (1.0 - l.discount)).setScale(2, System.RoundingMode.HALF_UP);
                ord.lines.add(l);
                ord.total += l.lineTotal;
            }
        }

        return ord;
    }

    public static String toAcknowledgement(OrderPayloadParser.Order order) {
        Map<String, Object> result = new Map<String, Object>();
        result.put('number', order.orderNumber);
        result.put('status', 'RECEIVED');
        result.put('lineCount', order.lines != null ? order.lines.size() : 0);
        result.put('total', order.total != null ? order.total : 0.0);
        return JSON.serialize(result);
    }
}
