public class OpportunityPipelineHandler {

    public static void handleTrigger() {
        Set<Id> accountIdsToRecalculate = new Set<Id>();

        if (Trigger.isInsert || Trigger.isUndelete) {
            for (Opportunity opp : (List<Opportunity>)Trigger.new) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    accountIdsToRecalculate.add(opp.AccountId);
                }
            }
        } else if (Trigger.isUpdate) {
            Map<Id, Opportunity> oldMap = (Map<Id, Opportunity>)Trigger.oldMap;
            for (Opportunity opp : (List<Opportunity>)Trigger.new) {
                Opportunity oldOpp = oldMap.get(opp.Id);

                Boolean accountChanged = opp.AccountId != oldOpp.AccountId;
                Boolean amountChanged = opp.Amount != oldOpp.Amount;
                Boolean statusChanged = opp.IsClosed != oldOpp.IsClosed;

                // Only flag accounts for recalculation if a relevant field actually changed
                if (accountChanged || amountChanged || statusChanged) {
                    if (!oldOpp.IsClosed && oldOpp.AccountId != null) {
                        accountIdsToRecalculate.add(oldOpp.AccountId);
                    }
                    if (!opp.IsClosed && opp.AccountId != null) {
                        accountIdsToRecalculate.add(opp.AccountId);
                    }
                }
            }
        } else if (Trigger.isDelete) {
            for (Opportunity opp : (List<Opportunity>)Trigger.old) {
                if (!opp.IsClosed && opp.AccountId != null) {
                    accountIdsToRecalculate.add(opp.AccountId);
                }
            }
        }

        if (!accountIdsToRecalculate.isEmpty()) {
            recalculateAccounts(accountIdsToRecalculate);
        }
    }

    private static void recalculateAccounts(Set<Id> accountIds) {
        // Run an aggregate query to get the open pipeline sums and counts for the affected accounts
        Map<Id, AggregateResult> aggregatedResults = new Map<Id, AggregateResult>();
        for (AggregateResult ar : [
            SELECT AccountId, SUM(Amount) totalAmount, COUNT(Id) totalCount 
            FROM Opportunity 
            WHERE AccountId IN :accountIds AND IsClosed = false 
            GROUP BY AccountId
        ]) {
            aggregatedResults.put((Id)ar.get('AccountId'), ar);
        }

        List<Account> accountsToUpdate = new List<Account>();

        // Query the existing account values to avoid infinite recursion loops with AccountTrigger
        // by updating only those accounts whose values have genuinely changed.
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c 
            FROM Account 
            WHERE Id IN :accountIds
        ]) {
            AggregateResult ar = aggregatedResults.get(acc.Id);

            Decimal totalAmount = 0;
            Integer totalCount = 0;

            if (ar != null) {
                totalAmount = ar.get('totalAmount') != null ? (Decimal)ar.get('totalAmount') : 0;
                totalCount = (Integer)ar.get('totalCount');
            }

            if (acc.FB_Open_Pipeline__c != totalAmount || acc.FB_Open_Opportunities__c != totalCount) {
                accountsToUpdate.add(new Account(
                    Id = acc.Id,
                    FB_Open_Pipeline__c = totalAmount,
                    FB_Open_Opportunities__c = totalCount
                ));
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
