            SELECT Id 
            FROM FB_Integration_Log__c 
            WHERE (Level__c = 'ERROR' AND CreatedDate < LAST_N_DAYS:180) 
               OR (Level__c != 'ERROR' AND CreatedDate < LAST_N_DAYS:30)
               OR (Level__c = NULL AND CreatedDate < LAST_N_DAYS:30)
        ]);
    }

    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        delete scope;
        Database.emptyRecycleBin(scope);
    }

    public void finish(Database.BatchableContext bc) {
    }

