public inherited sharing class CaseEscalationService {

    public class EscalationException extends Exception {}

    public static void escalate(Set<Id> caseIds, String reason) {
        if (String.isBlank(reason)) {
            throw new EscalationException('Reason cannot be blank');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> casesToProcess = CasesSelector.newInstance().selectById(caseIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();
        Boolean hasRecordsToCommit = false;

        for (Case c : casesToProcess) {
            if (c.Status == 'Closed' || c.IsEscalated) {
                continue;
            }

            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            Task t = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = Date.today().addDays(1),
                Priority = 'High'
            );
            uow.registerNew(t);

            hasRecordsToCommit = true;
        }

        if (hasRecordsToCommit) {
            uow.commitWork();
        }
    }
}
