public class AccountOnboardingService {
    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        // Define the SObject types in dependency order
        List<Schema.SObjectType> sObjectTypes = new List<Schema.SObjectType>{
            Account.SObjectType,
            Contact.SObjectType
        };

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(sObjectTypes);

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acc = new Account(Name = accountName);
            uow.registerNew(acc);
            newAccounts.add(acc);

            List<String> contactLastNames = contactLastNamesByAccountName.get(accountName);
            if (contactLastNames != null) {
                for (String lastName : contactLastNames) {
                    Contact con = new Contact(LastName = lastName);
                    // Register the new contact and automatically relate it to the account
                    uow.registerNew(con, Contact.AccountId, acc);
                }
            }
        }

        // Commit all records in one transaction
        uow.commitWork();

        // The Account records will now have their Ids populated
        return newAccounts;
    }
}
