public class StaleOpportunityCloser {

    /**
     * Closes open opportunities with a CloseDate before the given cutoff date.
     * 
     * Note on approach: 
     * While using a SOQL for loop with lists (chunking) helps manage heap size, 
     * this synchronous method is still subject to transaction governor limits:
     * - Maximum 10,000 DML rows per transaction.
     * - Maximum 150 DML statements per transaction.
     * - Maximum 50,000 SOQL query rows.
     * If there is any chance that the number of stale opportunities on a given night 
     * could exceed 10,000, this should be refactored into a Batch Apex class 
     * (Database.Batchable<sObject>) to safely process larger data volumes asynchronously 
     * without hitting governor limits.
     * 
     * @param cutoff The date before which open opportunities should be closed.
     * @return The total number of opportunities closed.
     */
    public static Integer closeStale(Date cutoff) {
        Integer closedCount = 0;

        // The SOQL for loop automatically retrieves records in chunks of 200
        for (List<Opportunity> chunk : [
            SELECT Id, StageName 
            FROM Opportunity 
            WHERE IsClosed = false 
              AND CloseDate < :cutoff
        ]) {
            for (Opportunity opp : chunk) {
                opp.StageName = 'Closed Lost';
            }

            update chunk;
            closedCount += chunk.size();
        }

        return closedCount;
    }
}
```

