public with sharing class CasePriorityHandler {
    public static void handleBeforeInsert(List<Case> newCases) {
        Set<Id> accountIds = new Set<Id>();

        // Collect Account IDs
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        // Query Accounts outside the loop to stay within the 100 SOQL query limit
        Map<Id, Account> accountMap = new Map<Id, Account>([
            SELECT Id, Rating 
            FROM Account 
            WHERE Id IN :accountIds
        ]);

        // Evaluate and set Case Priority
        for (Case c : newCases) {
            if (c.AccountId != null) {
                Account acc = accountMap.get(c.AccountId);
                if (acc != null && acc.Rating == 'Hot') {
                    c.Priority = 'High';
                }
            }
        }
    }
}
