public class ErpCustomerSync {

    /* 
     * DEVIATIONS FROM REQUIREMENTS:
     * 1. Async Context: Apex triggers do not support synchronous callouts. We must use an 
     *    asynchronous context (e.g., @future) to make the callout.
     * 2. Single Request vs Batch Request: The requirement asks for one request per new account. 
     *    However, since accounts can be inserted in batches of up to 200 by the marketplace integration, 
     *    making 200 individual callouts in a single transaction would exceed the Salesforce limit of 
     *    100 callouts per transaction. Therefore, we batch all accounts into a single request 
     *    using the array format supported by the ERP API (which perfectly handles 1 to 200 records).
     */

    public static void syncAccounts(List<Account> accounts) {
        if (accounts == null || accounts.isEmpty()) {
            return;
        }

        List<ErpCustomer> payloadList = new List<ErpCustomer>();
        for (Account acc : accounts) {
            ErpCustomer customer = new ErpCustomer();
            customer.salesforceId = acc.Id;
            customer.name = acc.Name;
            customer.country = acc.BillingCountry;
            payloadList.add(customer);
        }

        // Pass the serialized JSON to the future method to avoid querying the records again
        sendToErpAsync(JSON.serialize(payloadList));
    }

    @future(callout=true)
    private static void sendToErpAsync(String jsonPayload) {
        HttpRequest req = new HttpRequest();
        req.setEndpoint('callout:ERP/api/customers');
        req.setMethod('POST');
        req.setHeader('Content-Type', 'application/json');
        req.setBody(jsonPayload);

        Http http = new Http();
        // Error handling and retries are out of scope
        HttpResponse res = http.send(req);
    }

    // Wrapper class to form the JSON structure expected by the ERP
    private class ErpCustomer {
        public String salesforceId;
        public String name;
        public String country;
    }
}
