public with sharing class LineItemDiscountHandler {

    public static void handleBeforeInsert(List<OpportunityLineItem> newLines) {
        Set<Id> productIds = new Set<Id>();

        // Collect Product2Ids for lines that need a default discount
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIds.add(line.Product2Id);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // Bulk query the products to get their Families
        Map<Id, Product2> productMap = new Map<Id, Product2>([
            SELECT Id, Family 
            FROM Product2 
            WHERE Id IN :productIds
        ]);

        // Apply the discount using the family-level rule to avoid SOQL in loops
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                Product2 prod = productMap.get(line.Product2Id);
                if (prod != null) {
                    line.Discount = PricingRules.standardDiscountForFamily(prod.Family);
                }
            }
        }
    }
}
