import { LightningElement, api } from 'lwc';

export default class AccountContactList extends LightningElement {
    @api contacts;

    get hasContacts() {
        return this.contacts && this.contacts.length > 0;
    }

    get contactCountText() {
        if (!this.hasContacts) {
            return '';
        }
        const count = this.contacts.length;
        return count === 1 ? '1 contact' : `${count} contacts`;
    }

    get sortedContacts() {
        if (!this.hasContacts) {
            return [];
        }
        // Create a shallow copy to sort, as @api properties are read-only
        return [...this.contacts].sort((a, b) => {
            const nameA = a.Name || '';
            const nameB = b.Name || '';
            return nameA.localeCompare(nameB);
        });
    }
}
