import { LightningElement, api } from 'lwc';

export default class OrderLinesPanel extends LightningElement {
    @api lines = [];
    showError = false;

    handleReset() {
        const editors = this.template.querySelectorAll('c-line-item-editor');
        editors.forEach(editor => editor.reset());
    }

    handleSubmit() {
        const editors = Array.from(this.template.querySelectorAll('c-line-item-editor'));

        let isValid = true;
        // Validate all without short-circuiting so all errors are highlighted
        editors.forEach(editor => {
            if (!editor.validate()) {
                isValid = false;
            }
        });

        if (isValid) {
            this.showError = false;
            const submittedLines = editors.map(editor => editor.getValue());
            this.dispatchEvent(new CustomEvent('submit', {
                detail: { lines: submittedLines }
            }));
        } else {
            this.showError = true;
        }
    }
}
