import { LightningElement } from 'lwc';
import getQueueStats from '@salesforce/apex/QueueController.getQueueStats';

export default class QueueMonitor extends LightningElement {
    stats;
    error;
    inFlight = false;
    intervalId;

    connectedCallback() {
        this.boundVisibilityChange = this.handleVisibilityChange.bind(this);
        document.addEventListener('visibilitychange', this.boundVisibilityChange);

        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        }
    }

    disconnectedCallback() {
        this.stopPolling();
        document.removeEventListener('visibilitychange', this.boundVisibilityChange);
    }

    handleVisibilityChange() {
        if (document.visibilityState !== 'hidden') {
            this.startPolling();
        } else {
            this.stopPolling();
        }
    }

    startPolling() {
        if (!this.intervalId) {
            this.fetchStats();
            this.intervalId = setInterval(() => this.fetchStats(), 60000);
        }
    }

    stopPolling() {
        if (this.intervalId) {
            clearInterval(this.intervalId);
            this.intervalId = null;
        }
    }

    async fetchStats() {
        if (this.inFlight) {
            return;
        }

        this.inFlight = true;
        try {
            this.stats = await getQueueStats();
            this.error = null;
        } catch (err) {
            this.error = err.body ? err.body.message : 'Unknown error';
        } finally {
            this.inFlight = false;
        }
    }
}
