import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = null;
    _activeValue = null;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = val || [];
        this.updateActiveValue();
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val;
        this._activeValue = val;
        this.updateActiveValue();
    }

    updateActiveValue() {
        if (!this._options || this._options.length === 0) {
            return;
        }
        if (!this._activeValue || !this._options.find(o => o.value === this._activeValue)) {
            if (this._value && this._options.find(o => o.value === this._value)) {
                this._activeValue = this._value;
            } else {
                this._activeValue = this._options[0].value;
            }
        }
    }

    get computedOptions() {
        return (this._options || []).map((opt, index) => {
            return {
                ...opt,
                id: `opt-${index}`,
                selected: opt.value === this._value ? 'true' : 'false'
            };
        });
    }

    get activeId() {
        const options = this.computedOptions;
        const activeOpt = options.find(o => o.value === this._activeValue);
        return activeOpt ? activeOpt.id : '';
    }

    handleKeyDown(event) {
        const key = event.key;
        const keysToHandle = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!keysToHandle.includes(key)) {
            return;
        }

        event.preventDefault();

        const options = this._options || [];
        if (options.length === 0) {
            return;
        }

        let currentIndex = options.findIndex(o => o.value === this._activeValue);
        if (currentIndex === -1) {
            currentIndex = 0;
        }

        if (key === 'ArrowDown') {
            if (currentIndex < options.length - 1) {
                this._activeValue = options[currentIndex + 1].value;
            }
        } else if (key === 'ArrowUp') {
            if (currentIndex > 0) {
                this._activeValue = options[currentIndex - 1].value;
            }
        } else if (key === 'Home') {
            this._activeValue = options[0].value;
        } else if (key === 'End') {
            this._activeValue = options[options.length - 1].value;
        } else if (key === 'Enter' || key === ' ') {
            this.selectValue(this._activeValue);
        }
    }

    handleOptionClick(event) {
        const val = event.currentTarget.dataset.value;
        this._activeValue = val;
        this.selectValue(val);
    }

    selectValue(val) {
        if (this._value !== val) {
            this._value = val;
            this.dispatchEvent(new CustomEvent('change', { 
                detail: { value: val } 
            }));
        }
    }
}
