public class SoftCreditService {
    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) oppIds.add(req.opportunityId);
            if (req.contactId != null) contactIds.add(req.contactId);
        }

        // 1. Query Opportunities for validation
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c 
            FROM Opportunity 
            WHERE Id IN :oppIds
        ]);

        // Validate all requests before any DML
        for (SoftCreditRequest req : requests) {
            Opportunity opp = oppMap.get(req.opportunityId);
            if (opp != null) {
                if (req.contactId == opp.npsp__Primary_Contact__c) {
                    throw new SoftCreditException('Contact is the primary contact on the Opportunity.');
                }
                Decimal oppAmount = opp.Amount != null ? opp.Amount : 0;
                if (req.amount == null || req.amount <= 0 || req.amount > oppAmount) {
                    throw new SoftCreditException('Invalid amount for partial soft credit.');
                }
            }
        }

        // 2. Query existing OpportunityContactRoles
        List<OpportunityContactRole> existingOcrs = [
            SELECT Id, OpportunityId, ContactId, Role 
            FROM OpportunityContactRole 
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];

        Map<String, List<OpportunityContactRole>> ocrMap = new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : existingOcrs) {
            String key = ocr.OpportunityId + '-' + ocr.ContactId;
            if (!ocrMap.containsKey(key)) {
                ocrMap.put(key, new List<OpportunityContactRole>());
            }
            ocrMap.get(key).add(ocr);
        }

        // 3. Query existing Partial Soft Credits
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c 
            FROM npsp__Partial_Soft_Credit__c 
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];

        Map<String, npsp__Partial_Soft_Credit__c> pscMap = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
            String key = psc.npsp__Opportunity__c + '-' + psc.npsp__Contact__c;
            pscMap.put(key, psc);
        }

        List<OpportunityContactRole> ocrsToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpdate = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();

        Map<String, OpportunityContactRole> primaryOcrToUse = new Map<String, OpportunityContactRole>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            List<OpportunityContactRole> ocrs = ocrMap.get(key);

            OpportunityContactRole keptOcr;
            if (ocrs != null && !ocrs.isEmpty()) {
                keptOcr = ocrs[0];
                if (keptOcr.Role != req.role) {
                    keptOcr.Role = req.role;
                    ocrsToUpdate.add(keptOcr);
                }
                for (Integer i = 1; i < ocrs.size(); i++) {
                    ocrsToDelete.add(ocrs[i]);
                }
            } else {
                keptOcr = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                ocrsToInsert.add(keptOcr);
            }
            primaryOcrToUse.put(key, keptOcr);
        }

        // DML for OCRs
        if (!ocrsToInsert.isEmpty()) insert ocrsToInsert;
        if (!ocrsToUpdate.isEmpty()) update ocrsToUpdate;
        if (!ocrsToDelete.isEmpty()) delete ocrsToDelete;

        List<npsp__Partial_Soft_Credit__c> pscsToUpsert = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + '-' + req.contactId;
            OpportunityContactRole ocr = primaryOcrToUse.get(key);

            npsp__Partial_Soft_Credit__c psc = pscMap.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId
                );
            }
            psc.npsp__Amount__c = req.amount;
            psc.npsp__Role_Name__c = req.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);

            pscsToUpsert.add(psc);
        }

        // DML for PSCs
        if (!pscsToUpsert.isEmpty()) upsert pscsToUpsert;
    }
}
