public class GiftService {

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId 
            FROM Contact 
            WHERE Id = :contactId 
            LIMIT 1
        ];

        if (contacts.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }

        Contact donor = contacts[0];

        // Format the date as yyyy-MM-dd
        String dateStr = String.valueOf(giftDate).substring(0, 10);
        String oppName = (donor.FirstName != null ? donor.FirstName + ' ' : '') + donor.LastName + ' Donation ' + dateStr;

        // By inserting the Opportunity with npsp__Primary_Contact__c and AccountId, 
        // NPSP triggers will automatically create the appropriate Opportunity Contact Roles 
        // (Donor for primary contact, Household Member for others) and a Paid Payment 
        // (since it is Closed Won and NPSP Payments are enabled).
        Opportunity opp = new Opportunity(
            Name = oppName,
            AccountId = donor.AccountId,
            npsp__Primary_Contact__c = donor.Id,
            Amount = amount,
            CloseDate = giftDate,
            StageName = 'Closed Won'
        );

        insert opp;

        return opp.Id;
    }
}
