public class FamilyService {
    public static void linkParents(Map<Id, Id> parentIdByChildId) {
        if (parentIdByChildId == null || parentIdByChildId.isEmpty()) {
            return;
        }

        Set<Id> allIds = new Set<Id>();
        for (Id childId : parentIdByChildId.keySet()) {
            allIds.add(childId);
            allIds.add(parentIdByChildId.get(childId));
        }
        allIds.remove(null);

        if (allIds.isEmpty()) {
            return;
        }

        Set<String> existingPairs = new Set<String>();
        for (npe4__Relationship__c rel : [
            SELECT npe4__Contact__c, npe4__RelatedContact__c 
            FROM npe4__Relationship__c 
            WHERE npe4__Contact__c IN :allIds 
              AND npe4__RelatedContact__c IN :allIds
        ]) {
            Id c1 = rel.npe4__Contact__c;
            Id c2 = rel.npe4__RelatedContact__c;
            if (c1 != null && c2 != null) {
                String pair = c1 < c2 ? String.valueOf(c1) + String.valueOf(c2) : String.valueOf(c2) + String.valueOf(c1);
                existingPairs.add(pair);
            }
        }

        List<npe4__Relationship__c> relsToInsert = new List<npe4__Relationship__c>();
        for (Id childId : parentIdByChildId.keySet()) {
            Id parentId = parentIdByChildId.get(childId);
            if (childId == null || parentId == null || childId == parentId) {
                continue;
            }

            String pair = childId < parentId ? String.valueOf(childId) + String.valueOf(parentId) : String.valueOf(parentId) + String.valueOf(childId);

            if (!existingPairs.contains(pair)) {
                relsToInsert.add(new npe4__Relationship__c(
                    npe4__Contact__c = childId,
                    npe4__RelatedContact__c = parentId,
                    npe4__Type__c = 'Parent',
                    npe4__Status__c = 'Current'
                ));
                existingPairs.add(pair);
            }
        }

        if (!relsToInsert.isEmpty()) {
            insert relsToInsert;
        }
    }
}
