public with sharing class RecordAccessService {
    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editableIds = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editableIds;
        }

        List<Id> allIds = new List<Id>(recordIds);
        Id currentUserId = UserInfo.getUserId();

        // UserRecordAccess only supports querying up to 200 RecordIds at a time.
        Integer batchSize = 200;

        for (Integer i = 0; i < allIds.size(); i += batchSize) {
            List<Id> chunk = new List<Id>();
            for (Integer j = i; j < Math.min(i + batchSize, allIds.size()); j++) {
                chunk.add(allIds[j]);
            }

            for (UserRecordAccess ura : [
                SELECT RecordId 
                FROM UserRecordAccess 
                WHERE UserId = :currentUserId 
                  AND RecordId IN :chunk 
                  AND HasEditAccess = true
            ]) {
                editableIds.add(ura.RecordId);
            }
        }

        return editableIds;
    }
}
