public inherited sharing class ContactImportService {

    /**
     * Inserts contacts while bypassing the welcome task creation trigger action.
     * Ensures the bypass is removed after the DML operation.
     */
    public static void importContacts(List<Contact> contacts) {
        if (contacts == null || contacts.isEmpty()) {
            return;
        }

        // Bypass the specific trigger action for this transaction
        MetadataTriggerHandler.bypass('TA_Contact_CreateWelcomeTask');

        try {
            insert contacts;
        } finally {
            // Always clear the bypass, even if the insert fails
            MetadataTriggerHandler.clearBypass('TA_Contact_CreateWelcomeTask');
        }
    }
}
