public class TA_Contact_PreventDuplicateEmail implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        checkDuplicates((List<Contact>) triggerNew, null);
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldMap = new Map<Id, Contact>((List<Contact>) triggerOld);
        checkDuplicates((List<Contact>) triggerNew, oldMap);
    }

    private void checkDuplicates(List<Contact> newList, Map<Id, Contact> oldMap) {
        Map<String, Contact> checkMap = new Map<String, Contact>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();

        for (Contact c : newList) {
            if (c.AccountId != null && c.Email != null) {
                // For update, only process if AccountId or Email has changed
                if (oldMap == null || c.AccountId != oldMap.get(c.Id).AccountId || c.Email != oldMap.get(c.Id).Email) {
                    String key = String.valueOf(c.AccountId) + '|' + c.Email.toLowerCase();

                    // Check for duplicates within the current transaction (trigger batch)
                    if (checkMap.containsKey(key)) {
                        c.addError('Another contact on this account already uses this email address.');
                    } else {
                        checkMap.put(key, c);
                        accountIds.add(c.AccountId);
                        emails.add(c.Email);
                    }
                }
            }
        }

        // If there are valid contacts to evaluate, query the database for existing ones
        if (!checkMap.isEmpty()) {
            for (Contact existing : [
                SELECT Id, AccountId, Email 
                FROM Contact 
                WHERE AccountId IN :accountIds 
                AND Email IN :emails
            ]) {
                if (existing.Email != null && existing.AccountId != null) {
                    String key = String.valueOf(existing.AccountId) + '|' + existing.Email.toLowerCase();
                    Contact newContact = checkMap.get(key);

                    // Ensure we don't flag the same contact being updated as a duplicate of itself
                    if (newContact != null && newContact.Id != existing.Id) {
                        newContact.addError('Another contact on this account already uses this email address.');
                    }
                }
            }
        }
    }
}
