public class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> newList) {
        Set<Id> accIds = new Set<Id>();
        for (Case c : (List<Case>)newList) {
            if (c.AccountId != null && !c.IsClosed) {
                accIds.add(c.AccountId);
            }
        }
        updateAccounts(accIds);
    }

    public void afterUpdate(List<SObject> newList, List<SObject> oldList) {
        Set<Id> accIds = new Set<Id>();
        List<Case> newCases = (List<Case>)newList;
        List<Case> oldCases = (List<Case>)oldList;
        for (Integer i = 0; i < newCases.size(); i++) {
            Case nc = newCases[i];
            Case oc = oldCases[i];
            if (nc.AccountId != oc.AccountId || nc.IsClosed != oc.IsClosed) {
                if (nc.AccountId != null) {
                    accIds.add(nc.AccountId);
                }
                if (oc.AccountId != null) {
                    accIds.add(oc.AccountId);
                }
            }
        }
        updateAccounts(accIds);
    }

    public void afterDelete(List<SObject> oldList) {
        Set<Id> accIds = new Set<Id>();
        for (Case c : (List<Case>)oldList) {
            if (c.AccountId != null && !c.IsClosed) {
                accIds.add(c.AccountId);
            }
        }
        updateAccounts(accIds);
    }

    public void afterUndelete(List<SObject> newList) {
        Set<Id> accIds = new Set<Id>();
        for (Case c : (List<Case>)newList) {
            if (c.AccountId != null && !c.IsClosed) {
                accIds.add(c.AccountId);
            }
        }
        updateAccounts(accIds);
    }

    private void updateAccounts(Set<Id> accIds) {
        if (accIds.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsToUpdate = new Map<Id, Account>();
        for (Id accId : accIds) {
            accountsToUpdate.put(accId, new Account(Id = accId, FB_Open_Case_Count__c = 0));
        }

        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt
            FROM Case
            WHERE AccountId IN :accIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('AccountId');
            Decimal cnt = (Decimal) ar.get('cnt');
            accountsToUpdate.get(accId).FB_Open_Case_Count__c = cnt;
        }

        update accountsToUpdate.values();
    }
}
